function longestNoThrice(s: string): number {
  let best = 0;
  for (let i = 0; i < s.length; i++) {
    const count = new Array(26).fill(0);
    for (let j = i; j < s.length; j++) {
      if (++count[s.charCodeAt(j) - 97] > 2) break;
      best = Math.max(best, j - i + 1);
    }
  }
  return best;
}

