function longestNoThrice(s: string): number {
  const count = new Array(26).fill(0);
  let lo = 0, best = 0;
  for (let hi = 0; hi < s.length; hi++) {
    const c = s.charCodeAt(hi) - 97;
    count[c]++;
    while (count[c] > 2) count[s.charCodeAt(lo++) - 97]--;
    best = Math.max(best, hi - lo + 1);
  }
  return best;
}

